using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
class CompanionStoreTests {
 static List<string> checks=new List<string>();static void Check(bool v,string n){if(!v)throw new Exception(n);checks.Add(n);}static bool Reject(Action a){try{a();return false;}catch{return true;}}
 static void Main(string[] args){string root=Path.GetFullPath(args[0]),config=Path.Combine(root,"Settings"),home=Path.Combine(root,"Home");Directory.CreateDirectory(config);Store.Atomic(Path.Combine(config,"preferences.json"),Store.Json.Serialize(new Preferences{Home=home}));var store=new Store(config);var note=store.Create("Retained note","Keep this sentence.");store.SavePrefs();store.Pref.Theme="Charcoal";store.SavePrefs();Check(File.Exists(store.PrefsFile+".backup"),"valid preferences backup saved");File.WriteAllText(store.PrefsFile,"{damaged");var recovered=new Store(config);Check(recovered.Home==home,"custom home recovered from backup");Check(!String.IsNullOrEmpty(recovered.RecoveryNotice),"recovery is explained");Check(Directory.GetFiles(config,"preferences.json.damaged-*").Length==1,"damaged settings retained");Check(recovered.Notes.Any(n=>n.Body.Contains("Keep this sentence")),"notes retained through recovery");Check(Reject(()=>recovered.Resolve("../escape.md")),"parent traversal rejected");Check(Reject(()=>recovered.Resolve(Path.Combine(root,"outside.md"))),"absolute outside path rejected");Check(recovered.Resolve("Notes/example.md").StartsWith(home),"normal relative note accepted");string html=Store.Inline("<img src=x onerror=alert(1)> [bad](javascript:alert)");Check(!html.Contains("<img")&&!html.Contains("href='javascript:"),"note preview escapes active markup and URLs");var invalid=new Preferences{Quick=null,EditorSize=-200,WidgetOpacity=400,Opacity=-5,Width=-1,Height=-1};Store.NormalisePreferences(invalid);Check(invalid.Quick!=null&&invalid.EditorSize>=6&&invalid.WidgetOpacity==100&&invalid.Opacity==30&&invalid.Width>=320&&invalid.Height>=240,"invalid appearance settings normalised");string before=File.ReadAllText(note.Path);string trash=recovered.Trash(recovered.Notes.First(n=>n.Path==note.Path));Check(File.Exists(trash)&&File.ReadAllText(trash)==before,"deletion retains note in trash");File.WriteAllText(Path.Combine(root,"companion-store.json"),Store.Json.Serialize(new{ok=true,checks}));Console.WriteLine(checks.Count+" Companion storage checks passed");}
}
